INSERT INTO questions (id, exam_version_id, exam, supported_exams, skill, type_id, type_name, title, prompt, options, correct_answers, blanks, context_passage, explanation, difficulty, points, time_limit_seconds, is_published, passage_id, group_id, group_position) VALUES (
  $x$q-container-038$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE"}$x$::text[], 'reading', $x$fill-in-blanks-rw$x$, $x$Reading & Writing: Fill in the Blanks$x$, $x$The Box That Shrank the World$x$, $x$Cargo before the container$x$, NULL, NULL, $x$[{"id": "b1", "options": ["piece", "part", "item", "unit"], "correctAnswer": "piece"}, {"id": "b2", "options": ["cost", "weight", "speed", "risk"], "correctAnswer": "cost"}, {"id": "b3", "options": ["container", "harbour", "engine", "crane"], "correctAnswer": "container"}]$x$::jsonb, $x$Before the container, cargo was stowed [[b1]] by piece into a ship's hold, and a vessel could spend longer at a wharf than it spent at sea. Roughly half the [[b2]] of moving goods by sea was incurred while the ship was standing still. What changed this was not a new kind of ship but a new kind of [[b3]]: a steel box that could be lifted straight from a truck chassis onto a deck.$x$, $x$All three follow the wording of paragraphs A and B.$x$, $x$medium$x$, 10, 0, TRUE, $x$rp-container-01$x$, $x$g-container-9$x$, 1);
INSERT INTO questions (id, exam_version_id, exam, supported_exams, skill, type_id, type_name, title, prompt, options, correct_answers, blanks, context_passage, explanation, difficulty, points, time_limit_seconds, is_published, passage_id, group_id, group_position) VALUES (
  $x$q-container-039$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE"}$x$::text[], 'reading', $x$fill-in-blanks-rw$x$, $x$Reading & Writing: Fill in the Blanks$x$, $x$The Box That Shrank the World$x$, $x$From equipment to infrastructure$x$, NULL, NULL, $x$[{"id": "b1", "options": ["incompatibility", "cooperation", "expansion", "secrecy"], "correctAnswer": "incompatibility"}, {"id": "b2", "options": ["stacked", "painted", "weighed", "emptied"], "correctAnswer": "stacked"}, {"id": "b3", "options": ["infrastructure", "legislation", "decoration", "entertainment"], "correctAnswer": "infrastructure"}]$x$::jsonb, $x$The early years of containerisation were a period of expensive [[b1]], in which every operator built boxes to its own dimensions. What broke the deadlock was an international agreement on common sizes and on the corner castings by which a box is gripped and [[b2]]. Once a container built anywhere could be handled anywhere, it ceased to be one company's equipment and became [[b3]].$x$, $x$All three follow the wording of paragraphs D and E.$x$, $x$medium$x$, 10, 0, TRUE, $x$rp-container-01$x$, $x$g-container-9$x$, 2);

INSERT INTO reading_question_groups (id, passage_id, position, type_id, type_name, instructions, box_title, resources, passage_display, shuffle_questions, time_limit_seconds) VALUES (
  $x$g-container-10$x$, $x$rp-container-01$x$, 10, $x$fill-in-blanks-r$x$, $x$Reading: Fill in the Blanks$x$, $x$Drag words from the box below to the appropriate place in the text.$x$, $x$$x$, $x$[{"label": "w1", "text": "harbours"}, {"label": "w2", "text": "brittle"}, {"label": "w3", "text": "distance"}, {"label": "w4", "text": "deadlock"}, {"label": "w5", "text": "castings"}, {"label": "w6", "text": "chassis"}, {"label": "w7", "text": "empty"}, {"label": "w8", "text": "puzzle"}]$x$::jsonb, $x$hidden$x$, FALSE, 180);
INSERT INTO questions (id, exam_version_id, exam, supported_exams, skill, type_id, type_name, title, prompt, options, correct_answers, blanks, context_passage, explanation, difficulty, points, time_limit_seconds, is_published, passage_id, group_id, group_position) VALUES (
  $x$q-container-040$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE"}$x$::text[], 'reading', $x$fill-in-blanks-r$x$, $x$Reading: Fill in the Blanks$x$, $x$The Box That Shrank the World$x$, $x$Where the ships go$x$, NULL, NULL, $x$[{"id": "b1", "correctAnswer": "harbours"}, {"id": "b2", "correctAnswer": "brittle"}]$x$::jsonb, $x$A container port needs deep water and a great deal of flat land for stacking, requirements the old finger piers could not meet. Concentrating trade into so few deep-water [[b1]] has made the system [[b2]]: a single vessel wedged across a canal now propagates through economies with no slack left in them.$x$, $x$Both words are taken from paragraphs G and J.$x$, $x$medium$x$, 10, 0, TRUE, $x$rp-container-01$x$, $x$g-container-10$x$, 1);
INSERT INTO questions (id, exam_version_id, exam, supported_exams, skill, type_id, type_name, title, prompt, options, correct_answers, blanks, context_passage, explanation, difficulty, points, time_limit_seconds, is_published, passage_id, group_id, group_position) VALUES (
  $x$q-container-041$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE"}$x$::text[], 'reading', $x$fill-in-blanks-r$x$, $x$Reading: Fill in the Blanks$x$, $x$The Box That Shrank the World$x$, $x$The collapse of distance$x$, NULL, NULL, $x$[{"id": "b1", "correctAnswer": "distance"}, {"id": "b2", "correctAnswer": "deadlock"}]$x$::jsonb, $x$When moving a component across an ocean costs less than moving it across a country by road, [[b1]] stops being expensive and each stage of production can go wherever it is cheapest. What broke the early [[b2]] over incompatible box sizes was an international standard.$x$, $x$Both words are taken from paragraphs E and I.$x$, $x$medium$x$, 10, 0, TRUE, $x$rp-container-01$x$, $x$g-container-10$x$, 2);

INSERT INTO reading_passages (id, exam_version_id, title, subtitle, paragraphs, sources, word_count, difficulty, topic, tags, is_published) VALUES (
  $x$rp-icecore-01$x$, $x$ielts-2026-01$x$, $x$Reading the Ice$x$, $x$What a frozen column of snow remembers about the atmosphere$x$, $x$[{"label": "A", "text": "An ice sheet is, among other things, a filing system. Snow that falls on the interior of Antarctica almost never melts; it is buried by the next season's fall, compressed by the weight above it, and slowly turned to ice. As it compacts, the spaces between the grains pinch shut, sealing off small pockets of the air that happened to be there at the time. A vertical column drilled from such a sheet is therefore not merely frozen water. It is a stack of samples, in order, of the atmosphere itself."}, {"label": "B", "text": "Recovering that column is a considerable engineering exercise. A drill is lowered on a cable, cuts a cylinder perhaps three metres long, and is winched back to the surface, a cycle that is repeated for years. Below a few hundred metres the pressure of the surrounding ice would close the hole, so the borehole is filled with a dense fluid to hold it open. Work is confined to the short polar summer, and a deep core may take five or six field seasons to complete."}, {"label": "C", "text": "Dating the column is a separate problem. Near the surface, each year leaves a visible layer, and these can be counted much as tree rings are. Deeper down the layers thin under the weight above until counting becomes impossible, and the chronology has to be built from flow models instead. Fortunately the ice contains fixed points: a large volcanic eruption lays down a thin horizon of ash and sulphuric acid across the whole continent, and a horizon of known date anchors everything around it."}, {"label": "D", "text": "The trapped bubbles are what make the archive unusual. Most of what is known about ancient climate is inferred from proxies, from the chemistry of shells or the width of tree rings, and inference always carries assumptions. The air in an ice core requires none. A bubble from a hundred thousand years ago can be crushed in a laboratory and its carbon dioxide measured directly. It is one of the few places in earth science where the past can be sampled rather than reconstructed."}, {"label": "E", "text": "Temperature is not sampled directly, but it is close. Water molecules containing the heavier isotopes of oxygen and hydrogen evaporate slightly less readily and condense slightly more readily than ordinary ones, so the ratio of heavy to light isotopes in the snow depends on how cold it was when the snow formed. Measured down the length of a core, that ratio becomes a thermometer reading backwards in time, calibrated against modern snowfall."}, {"label": "F", "text": "The results reshaped the field. The Vostok core, completed in the 1990s, reached back some four hundred thousand years; the European project at Dome C later doubled that, passing eight hundred thousand. Both showed the same striking pattern: long glacial periods lasting roughly a hundred thousand years, ended abruptly by short warm intervals, repeating with a regularity that demanded explanation."}, {"label": "G", "text": "They also showed that carbon dioxide and temperature rose and fell together throughout. This correlation is frequently quoted, and frequently misused in both directions. It does not by itself show that the gas drove the temperature; over the glacial cycles the initial push came from slow changes in the earth's orbit, and the gas followed. What it does show is that the two are tightly coupled, and that the carbon dioxide released as the oceans warmed then amplified the warming considerably."}, {"label": "H", "text": "The most unsettling finding came from the other pole. Cores drilled through the Greenland ice sheet revealed episodes in which the local temperature rose by something close to ten degrees within a single decade, and then held. Before this, most researchers had pictured climate change as a gradual affair operating over millennia. The Greenland record showed a system that could also jump, and the question of what could make it jump has occupied the field ever since."}, {"label": "I", "text": "Attention has now turned to older ice. Somewhere before a million years ago the rhythm of the ice ages changed, from a cycle of roughly forty-one thousand years to the hundred-thousand-year cycle of more recent times, and nobody is certain why. Answering it requires air from that period, which means finding a patch of Antarctica where ancient ice survives undisturbed near the bedrock. Sites have been surveyed for years, and drilling for ice a million and a half years old is now under way."}, {"label": "J", "text": "The archive has limits, and they are worth stating. Deep ice flows, and near the bedrock the layers may be folded or overturned, which destroys their order. Occasional melting at the base removes the record entirely. The bubbles seal some decades after the snow falls, so the air is always slightly younger than the ice around it, an offset that must be estimated rather than measured. None of this makes the archive unreliable. It makes it a document that has to be read with care, like any other old manuscript."}]$x$::jsonb, '[]'::jsonb, 808, $x$hard$x$, $x$climate science$x$, $x${"science","climate","antarctica","research"}$x$::text[], TRUE);

