  $x$q-icecore-036$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE","IELTS"}$x$::text[], 'reading', $x$reading-mcq-multiple$x$, $x$Multiple Choice, Multiple Answers$x$, $x$Reading the Ice$x$, $x$Which TWO limits of the ice-core record does the writer describe?$x$, $x$[{"id": "Deep layers may be folded or overturned by flowing ice", "text": "Deep layers may be folded or overturned by flowing ice"}, {"id": "Melting at the base can remove the record entirely", "text": "Melting at the base can remove the record entirely"}, {"id": "The bubbles lose their carbon dioxide over time", "text": "The bubbles lose their carbon dioxide over time"}, {"id": "Isotope ratios cannot be measured below a certain depth", "text": "Isotope ratios cannot be measured below a certain depth"}, {"id": "Volcanic ash contaminates the trapped air", "text": "Volcanic ash contaminates the trapped air"}]$x$::jsonb, $x$["Deep layers may be folded or overturned by flowing ice", "Melting at the base can remove the record entirely"]$x$::jsonb, NULL, NULL, $x$Both appear in paragraph J.$x$, $x$hard$x$, 10, 0, TRUE, $x$rp-icecore-01$x$, $x$g-icecore-8$x$, 1);
