  $x$q-icecore-037$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE","IELTS"}$x$::text[], 'reading', $x$reading-mcq-multiple$x$, $x$Multiple Choice, Multiple Answers$x$, $x$Reading the Ice$x$, $x$Which TWO things does the passage say the ice cores revealed about glacial cycles?$x$, $x$[{"id": "Glacial periods lasted roughly a hundred thousand years", "text": "Glacial periods lasted roughly a hundred thousand years"}, {"id": "Carbon dioxide and temperature rose and fell together", "text": "Carbon dioxide and temperature rose and fell together"}, {"id": "The cycles were caused entirely by volcanic eruptions", "text": "The cycles were caused entirely by volcanic eruptions"}, {"id": "Each cycle was longer than the one before it", "text": "Each cycle was longer than the one before it"}, {"id": "Warm intervals lasted longer than cold ones", "text": "Warm intervals lasted longer than cold ones"}]$x$::jsonb, $x$["Glacial periods lasted roughly a hundred thousand years", "Carbon dioxide and temperature rose and fell together"]$x$::jsonb, NULL, NULL, $x$Paragraph F gives the length; paragraph G gives the coupling.$x$, $x$hard$x$, 10, 0, TRUE, $x$rp-icecore-01$x$, $x$g-icecore-8$x$, 2);

