INSERT INTO questions (id, exam_version_id, exam, supported_exams, skill, type_id, type_name, title, prompt, options, correct_answers, blanks, context_passage, explanation, difficulty, points, time_limit_seconds, is_published, passage_id, group_id, group_position) VALUES (
  $x$q-icecore-038$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE"}$x$::text[], 'reading', $x$fill-in-blanks-rw$x$, $x$Reading & Writing: Fill in the Blanks$x$, $x$Reading the Ice$x$, $x$The archive in the ice$x$, NULL, NULL, $x$[{"id": "b1", "options": ["compressed", "dissolved", "scattered", "warmed"], "correctAnswer": "compressed"}, {"id": "b2", "options": ["crushed", "frozen", "buried", "diluted"], "correctAnswer": "crushed"}, {"id": "b3", "options": ["reconstructed", "photographed", "discarded", "translated"], "correctAnswer": "reconstructed"}]$x$::jsonb, $x$Snow falling on the Antarctic interior is buried and [[b1]] by the weight above it until the spaces between the grains pinch shut. The pockets of air sealed in this way can later be [[b2]] in a laboratory and their carbon dioxide measured directly, which is why the record is described as sampled rather than [[b3]].$x$, $x$The wording follows paragraphs A and D.$x$, $x$hard$x$, 10, 0, TRUE, $x$rp-icecore-01$x$, $x$g-icecore-9$x$, 1);
INSERT INTO questions (id, exam_version_id, exam, supported_exams, skill, type_id, type_name, title, prompt, options, correct_answers, blanks, context_passage, explanation, difficulty, points, time_limit_seconds, is_published, passage_id, group_id, group_position) VALUES (
  $x$q-icecore-039$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE"}$x$::text[], 'reading', $x$fill-in-blanks-rw$x$, $x$Reading & Writing: Fill in the Blanks$x$, $x$Reading the Ice$x$, $x$A thermometer in the snow$x$, NULL, NULL, $x$[{"id": "b1", "options": ["readily", "recently", "loudly", "densely"], "correctAnswer": "readily"}, {"id": "b2", "options": ["temperature", "altitude", "pressure", "latitude"], "correctAnswer": "temperature"}, {"id": "b3", "options": ["calibrated", "exchanged", "concealed", "abandoned"], "correctAnswer": "calibrated"}]$x$::jsonb, $x$Water molecules built from heavier isotopes evaporate slightly less [[b1]] than ordinary ones, so the proportion of heavy to light isotopes in fallen snow depends on the [[b2]] at which it formed. Measured along a core, that proportion becomes a record reading backwards in time, [[b3]] against modern snowfall.$x$, $x$The wording follows paragraph E.$x$, $x$hard$x$, 10, 0, TRUE, $x$rp-icecore-01$x$, $x$g-icecore-9$x$, 2);

INSERT INTO reading_question_groups (id, passage_id, position, type_id, type_name, instructions, box_title, resources, passage_display, shuffle_questions, time_limit_seconds) VALUES (
  $x$g-icecore-10$x$, $x$rp-icecore-01$x$, 10, $x$fill-in-blanks-r$x$, $x$Reading: Fill in the Blanks$x$, $x$Drag words from the box below to the appropriate place in the text.$x$, $x$$x$, $x$[{"label": "w1", "text": "bedrock"}, {"label": "w2", "text": "decade"}, {"label": "w3", "text": "orbit"}, {"label": "w4", "text": "fluid"}, {"label": "w5", "text": "horizon"}, {"label": "w6", "text": "bubbles"}, {"label": "w7", "text": "seasons"}, {"label": "w8", "text": "manuscript"}]$x$::jsonb, $x$hidden$x$, FALSE, 180);
INSERT INTO questions (id, exam_version_id, exam, supported_exams, skill, type_id, type_name, title, prompt, options, correct_answers, blanks, context_passage, explanation, difficulty, points, time_limit_seconds, is_published, passage_id, group_id, group_position) VALUES (
  $x$q-icecore-040$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE"}$x$::text[], 'reading', $x$fill-in-blanks-r$x$, $x$Reading: Fill in the Blanks$x$, $x$Reading the Ice$x$, $x$Getting the ice out$x$, NULL, NULL, $x$[{"id": "b1", "correctAnswer": "fluid"}, {"id": "b2", "correctAnswer": "seasons"}]$x$::jsonb, $x$Below a few hundred metres the surrounding ice would close the hole, so the borehole is held open with a dense [[b1]]. Because work is possible only in the short polar summer, a deep core may take five or six field [[b2]] to finish.$x$, $x$Both words are taken from paragraph B.$x$, $x$hard$x$, 10, 0, TRUE, $x$rp-icecore-01$x$, $x$g-icecore-10$x$, 1);
INSERT INTO questions (id, exam_version_id, exam, supported_exams, skill, type_id, type_name, title, prompt, options, correct_answers, blanks, context_passage, explanation, difficulty, points, time_limit_seconds, is_published, passage_id, group_id, group_position) VALUES (
  $x$q-icecore-041$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE"}$x$::text[], 'reading', $x$fill-in-blanks-r$x$, $x$Reading: Fill in the Blanks$x$, $x$Reading the Ice$x$, $x$What the ice cannot say$x$, NULL, NULL, $x$[{"id": "b1", "correctAnswer": "decade"}, {"id": "b2", "correctAnswer": "bedrock"}]$x$::jsonb, $x$Cores from Greenland showed local temperature rising by close to ten degrees within a single [[b1]], which overturned the assumption of gradual change. Even so, the record has limits: near the [[b2]] the layers may be folded, and their order is lost.$x$, $x$Both words are taken from paragraphs H and J.$x$, $x$hard$x$, 10, 0, TRUE, $x$rp-icecore-01$x$, $x$g-icecore-10$x$, 2);

INSERT INTO reading_passages (id, exam_version_id, title, subtitle, paragraphs, sources, word_count, difficulty, topic, tags, is_published) VALUES (
  $x$rp-seedvault-01$x$, $x$ielts-2026-01$x$, $x$Banking the Harvest$x$, $x$Why the world keeps a frozen library of seeds, and what it cannot preserve$x$, $x$[{"label": "A", "text": "Agriculture has spent the last century getting narrower. A crop that was once grown as hundreds of local varieties, each suited to a particular soil, season or taste, is now grown across whole continents as a handful of high-yielding cultivars. The gain in productivity has been enormous and is not in dispute. The cost is that the varieties left out of the modern fields carried traits nobody thought to want at the time, resistance to a disease that had not yet arrived, tolerance of a drought that had not yet happened, and once a variety stops being sown it is generally gone within a generation."}, {"label": "B", "text": "The response has been to collect and store. A seed bank, or gene bank, holds samples of as many varieties of a crop as it can obtain, each sample known as an accession and each accompanied by a record of where it came from. There are roughly seventeen hundred such collections around the world, ranging from national institutions holding hundreds of thousands of accessions to small university collections devoted to a single species. Together they represent the largest deliberate act of biological archiving ever attempted."}, {"label": "C", "text": "The storage itself is unglamorous. Seeds are dried until their moisture content is very low, sealed in foil packets and held at around minus eighteen degrees. Under those conditions many species remain capable of germinating for decades and some for centuries. This is not permanent: viability falls slowly, so a bank must periodically take a sample out, grow it, and harvest fresh seed to replace the old. Regeneration is the expensive part of the work, and the part most often skipped when budgets are cut."}, {"label": "D", "text": "Individual collections turn out to be fragile in ways that have nothing to do with biology. A gene bank depends on continuous electricity, continuous funding and a country at peace, and over the past fifty years collections have been lost to all three failing. Banks have been destroyed by war, by flooding, by a fire that followed the flooding, and by the quieter process of a government deciding that a refrigerated warehouse of old seed is not a priority this year. The samples inside were, in most cases, the only ones in existence."}, {"label": "E", "text": "This is the argument for Svalbard. Opened in 2008 in a mountainside on a Norwegian island well inside the Arctic Circle, the Global Seed Vault stores nothing that is not already held somewhere else. It is a backup of backups. The surrounding permafrost keeps the chambers cold even if the refrigeration and the power both fail, and the vault takes no ownership of what it holds: each box remains the property of the institution that sent it, and only that institution may ask for it back."}, {"label": "F", "text": "The arrangement was tested sooner than anyone expected. The regional collection for the dry areas of the Middle East had been held in Aleppo, and by 2015 the war in Syria had made the site impossible to operate. Its staff had deposited duplicates at Svalbard, and in that year they made the vault's first withdrawal, rebuilding the collection at new sites in Lebanon and Morocco. Within a few years those rebuilt collections were sending fresh duplicates back to the mountain, which is exactly the cycle the vault was designed for."}, {"label": "G", "text": "For all that, a frozen seed is a snapshot rather than a living thing. A variety kept at minus eighteen degrees stops evolving the moment it goes in. The pests and diseases outside do not stop, nor does the climate, so a sample withdrawn after forty years returns to a world that has moved on without it. A gene bank preserves the raw material of adaptation extremely well, and preserves adaptation itself not at all."}, {"label": "H", "text": "That is the case for the other approach, which is to keep varieties growing. On-farm conservation supports the farmers who still sow local landraces, on the reasoning that a variety maintained in a field continues to meet whatever the field throws at it. Its weakness is the mirror image of the vault's: a living population can be wiped out by one bad season or one economic decision. The two methods are frequently presented as rivals. They are better understood as answers to different halves of the same problem."}, {"label": "I", "text": "Some crops cannot be banked at all. The seeds of cocoa, coffee, avocado and rubber are what botanists call recalcitrant: they will not survive being dried, and freezing them kills them outright. Such species have to be maintained either as living trees in field collections, which occupy land and are exposed to every hazard an orchard faces, or through cryopreservation, in which fragments of tissue are held in liquid nitrogen. The second is effective and expensive, and has been worked out for only a fraction of the species that need it."}, {"label": "J", "text": "Underneath all of this sits an unresolved question of ownership. Most crop diversity was produced over thousands of years by farmers in regions that are not, on the whole, the regions where commercial plant breeding now takes place. An international treaty attempts to balance this by granting breeders access to a shared pool in return for sharing the benefits of what they develop from it. Whether the benefits have flowed in any meaningful quantity is disputed, and the dispute matters: a system of collection that the countries holding the diversity come to regard as extraction will not keep receiving deposits."}]$x$::jsonb, '[]'::jsonb, 898, $x$medium$x$, $x$agriculture and conservation$x$, $x${"agriculture","conservation","science","policy"}$x$::text[], TRUE);

