INSERT INTO questions (id, exam_version_id, exam, supported_exams, skill, type_id, type_name, title, prompt, options, correct_answers, blanks, context_passage, explanation, difficulty, points, time_limit_seconds, is_published, passage_id, group_id, group_position) VALUES (
  $x$q-seedvault-038$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE"}$x$::text[], 'reading', $x$fill-in-blanks-rw$x$, $x$Reading & Writing: Fill in the Blanks$x$, $x$Banking the Harvest$x$, $x$Why collections are fragile$x$, NULL, NULL, $x$[{"id": "b1", "options": ["peace", "debt", "drought", "isolation"], "correctAnswer": "peace"}, {"id": "b2", "options": ["existence", "season", "storage", "question"], "correctAnswer": "existence"}, {"id": "b3", "options": ["duplicates", "records", "photographs", "profits"], "correctAnswer": "duplicates"}]$x$::jsonb, $x$A gene bank depends on continuous electricity, continuous funding and a country at [[b1]], and collections have been lost when any of the three has failed. Because the samples inside were often the only ones in [[b2]], the loss is permanent. The answer has been to keep [[b3]] of each collection somewhere far away.$x$, $x$The wording follows paragraphs D and E.$x$, $x$medium$x$, 10, 0, TRUE, $x$rp-seedvault-01$x$, $x$g-seedvault-9$x$, 1);
INSERT INTO questions (id, exam_version_id, exam, supported_exams, skill, type_id, type_name, title, prompt, options, correct_answers, blanks, context_passage, explanation, difficulty, points, time_limit_seconds, is_published, passage_id, group_id, group_position) VALUES (
  $x$q-seedvault-039$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE"}$x$::text[], 'reading', $x$fill-in-blanks-rw$x$, $x$Reading & Writing: Fill in the Blanks$x$, $x$Banking the Harvest$x$, $x$A snapshot, not a living thing$x$, NULL, NULL, $x$[{"id": "b1", "options": ["evolving", "germinating", "spreading", "flowering"], "correctAnswer": "evolving"}, {"id": "b2", "options": ["sow", "sell", "import", "catalogue"], "correctAnswer": "sow"}, {"id": "b3", "options": ["half", "century", "region", "budget"], "correctAnswer": "half"}]$x$::jsonb, $x$A variety held at minus eighteen degrees stops [[b1]] the moment it goes into store, while the pests and the climate outside carry on changing. A sample withdrawn after forty years therefore returns to a world that has moved on, which is the argument for also supporting farmers who continue to [[b2]] local landraces. The two approaches are often treated as rivals, but each answers a different [[b3]] of the problem.$x$, $x$The wording follows paragraphs G and H.$x$, $x$medium$x$, 10, 0, TRUE, $x$rp-seedvault-01$x$, $x$g-seedvault-9$x$, 2);

INSERT INTO reading_question_groups (id, passage_id, position, type_id, type_name, instructions, box_title, resources, passage_display, shuffle_questions, time_limit_seconds) VALUES (
  $x$g-seedvault-10$x$, $x$rp-seedvault-01$x$, 10, $x$fill-in-blanks-r$x$, $x$Reading: Fill in the Blanks$x$, $x$Drag words from the box below to the appropriate place in the text.$x$, $x$$x$, $x$[{"label": "w1", "text": "accession"}, {"label": "w2", "text": "permafrost"}, {"label": "w3", "text": "extraction"}, {"label": "w4", "text": "nitrogen"}, {"label": "w5", "text": "cultivars"}, {"label": "w6", "text": "harvest"}, {"label": "w7", "text": "treaty"}, {"label": "w8", "text": "orchard"}]$x$::jsonb, $x$hidden$x$, FALSE, 180);
INSERT INTO questions (id, exam_version_id, exam, supported_exams, skill, type_id, type_name, title, prompt, options, correct_answers, blanks, context_passage, explanation, difficulty, points, time_limit_seconds, is_published, passage_id, group_id, group_position) VALUES (
  $x$q-seedvault-040$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE"}$x$::text[], 'reading', $x$fill-in-blanks-r$x$, $x$Reading: Fill in the Blanks$x$, $x$Banking the Harvest$x$, $x$The vault in the mountain$x$, NULL, NULL, $x$[{"id": "b1", "correctAnswer": "permafrost"}, {"id": "b2", "correctAnswer": "accession"}]$x$::jsonb, $x$The chambers at Svalbard are surrounded by [[b1]], which keeps them cold even if the refrigeration and the power both fail. Each sample deposited there is recorded as a single [[b2]], accompanied by a note of where it originally came from.$x$, $x$Both words are taken from paragraphs B and E.$x$, $x$medium$x$, 10, 0, TRUE, $x$rp-seedvault-01$x$, $x$g-seedvault-10$x$, 1);
INSERT INTO questions (id, exam_version_id, exam, supported_exams, skill, type_id, type_name, title, prompt, options, correct_answers, blanks, context_passage, explanation, difficulty, points, time_limit_seconds, is_published, passage_id, group_id, group_position) VALUES (
  $x$q-seedvault-041$x$, $x$pte-2026-01$x$, $x$PTE$x$, $x${"PTE"}$x$::text[], 'reading', $x$fill-in-blanks-r$x$, $x$Reading: Fill in the Blanks$x$, $x$Banking the Harvest$x$, $x$Who owns the diversity$x$, NULL, NULL, $x$[{"id": "b1", "correctAnswer": "treaty"}, {"id": "b2", "correctAnswer": "extraction"}]$x$::jsonb, $x$An international [[b1]] grants breeders access to a shared pool of crop diversity in return for sharing what they develop from it. If the countries that hold the diversity come to see the arrangement as [[b2]], they will stop contributing to it.$x$, $x$Both words are taken from paragraph J.$x$, $x$medium$x$, 10, 0, TRUE, $x$rp-seedvault-01$x$, $x$g-seedvault-10$x$, 2);

DO $guard$
DECLARE
    complete INT;
BEGIN
    SELECT count(*) INTO complete
    FROM reading_passages p
    WHERE p.id IN ('rp-container-01', 'rp-icecore-01', 'rp-seedvault-01')
      AND p.is_published
      AND (SELECT count(DISTINCT g.type_id)
           FROM reading_question_groups g
           WHERE g.passage_id = p.id
             AND EXISTS (SELECT 1 FROM questions q WHERE q.group_id = g.id AND q.is_published)) = 10;

    IF complete <> 3 THEN
        RAISE EXCEPTION 'reading batch 2: % of 3 passages carry all ten task types', complete;
    END IF;
END
$guard$;

DO $keys$
DECLARE
    broken INT;
BEGIN
    SELECT count(*) INTO broken
    FROM questions q
    WHERE q.passage_id IN ('rp-container-01', 'rp-icecore-01', 'rp-seedvault-01')
      AND q.options IS NOT NULL
      AND jsonb_array_length(q.options) > 0
      AND EXISTS (
          SELECT 1 FROM jsonb_array_elements_text(q.correct_answers) AS a
          WHERE NOT EXISTS (
              SELECT 1 FROM jsonb_array_elements(q.options) AS o WHERE o->>'id' = a
          )
      );

    IF broken > 0 THEN
        RAISE EXCEPTION 'reading batch 2: % answer keys name an option that does not exist', broken;
    END IF;
END
$keys$;

DO $gaps$
DECLARE
    broken INT;
BEGIN
    SELECT count(*) INTO broken
    FROM questions q
    WHERE q.passage_id IN ('rp-container-01', 'rp-icecore-01', 'rp-seedvault-01')
      AND q.blanks IS NOT NULL
      AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(q.blanks) AS b
          WHERE coalesce(b->>'correctAnswer', '') = ''
      );

    IF broken > 0 THEN
        RAISE EXCEPTION 'reading batch 2: % gapped texts have an unanswered gap', broken;
    END IF;
END
$gaps$;
